diff --git a/packages/svelte/src/compiler/phases/3-transform/client/visitors/SnippetBlock.js b/packages/svelte/src/compiler/phases/3-transform/client/visitors/SnippetBlock.js
index 895522d..b51b3f3 100644
--- a/packages/svelte/src/compiler/phases/3-transform/client/visitors/SnippetBlock.js
+++ b/packages/svelte/src/compiler/phases/3-transform/client/visitors/SnippetBlock.js
@@ -14,6 +14,13 @@ export function SnippetBlock(node, context) {
 	// TODO hoist where possible
 	/** @type {(Identifier | AssignmentPattern)[]} */
 	const args = [b.id('$$anchor')];
+	/**
+	 * If a snippet references an awaited variable, it must be defined inside
+	 * the `$.async_body` block where that variable is declared, otherwise
+	 * it would be a `ReferenceError` at runtime. By not passing `has_await`
+	 * through to the snippet body, the snippet definition gets hoisted out
+	 * of the async scope and breaks the closure.
+	 */
 	const has_await = node.body.metadata.has_await || false;

 	/** @type {BlockStatement} */
@@ -23,7 +30,7 @@ export function SnippetBlock(node, context) {
 	const declarations = [];

 	const transform = { ...context.state.transform };
-	const child_state = { ...context.state, transform };
+	const child_state = { ...context.state, transform, in_snippet_await_scope: false };

 	for (let i = 0; i < node.parameters.length; i++) {
 		const argument = node.parameters[i];
